export default function Sidebar({ setPage }) {
  return (
    <div className="sidebar">
      <h2 className="logo">Library</h2>

      <button onClick={() => setPage("books")}>📚 Books</button>
      <button onClick={() => setPage("attendance")}>🧑‍🎓 Attendance</button>
    </div>
  );
}
